#include "veml6030.h"
#include "sl_i2cspm.h"
#include "sl_i2cspm_instances.h"
#include "em_i2c.h"         // for I2C_TransferSeq_TypeDef
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

// Use the I2C instance generated by Simplicity Studio's configuration
extern sl_i2cspm_t *sl_i2cspm_mikroe;


// VEML6030 I2C 7-bit address
#define VEML6030_ADDR         0x48

// VEML6030 Register Addresses
#define ALS_CONF_REG          0x00
#define ALS_REG               0x04
#define WHITE_REG             0x05
#define ALS_WH_REG            0x01
#define ALS_WL_REG            0x02

// Internal I2C write function
static void veml6030_write(uint8_t reg, uint16_t value) {
    uint8_t data[3] = {
        reg,
        (uint8_t)(value & 0xFF),
        (uint8_t)((value >> 8) & 0xFF)
    };

    I2C_TransferSeq_TypeDef seq = {
        .addr = VEML6030_ADDR << 1,
        .flags = I2C_FLAG_WRITE,
        .buf[0] = { .data = data, .len = 3 },
        .buf[1] = { .data = NULL, .len = 0 }
    };

    I2CSPM_Transfer(sl_i2cspm_mikroe, &seq);
}

// Internal I2C read function
static uint16_t veml6030_read(uint8_t reg) {
    uint8_t rx[2];

    I2C_TransferSeq_TypeDef seq = {
        .addr = VEML6030_ADDR << 1,
        .flags = I2C_FLAG_WRITE_READ,
        .buf[0] = { .data = &reg, .len = 1 },
        .buf[1] = { .data = rx, .len = 2 }
    };

    I2CSPM_Transfer(sl_i2cspm_mikroe, &seq);
    return rx[0] | (rx[1] << 8);
}

// Public API

void VEML6030_init(void) {
    // Default config: gain=1x, itime=100ms, pers=1, int_en=0, SD=0 (powered on)
    VEML6030_config(0x00, 0x02, 0x00, false, false);
}

void VEML6030_config(uint8_t gain, uint8_t ALS_integration, uint8_t ALS_persistence, bool INT_en, bool SD) {
    uint16_t config = (gain << 11) | (ALS_integration << 6) | (ALS_persistence << 4) | (INT_en << 1) | SD;
    config &= 0x1BF3;  // mask reserved bits
    veml6030_write(ALS_CONF_REG, config);
}

void power_on(void) {
    VEML6030_config(0x00, 0x02, 0x00, false, false);
}

void set_white_High_tresh(uint16_t thresholdHigh) {
    veml6030_write(ALS_WH_REG, thresholdHigh);
}

void set_white_Low_tresh(uint16_t thresholdLow) {
    veml6030_write(ALS_WL_REG, thresholdLow);
}

uint16_t Get_ambient(void) {
    return veml6030_read(ALS_REG);
}

uint16_t Get_white(void) {
    return veml6030_read(WHITE_REG);
}

